import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlContentHeaderComponent, VlTemplate } from '@domg-wc/components/block';
import { VlFooter, VlHeader } from '@domg-wc/components/compliance';

// De identifiers van vl-header en vl-footer zijn die van de story. Een eigen identifier vraag je aan bij Team Infra
// van Departement Omgeving of via het stappenplan van Digitaal Vlaanderen. development gebruikt de
// ontwikkel-servers van Digitaal Vlaanderen.
registerWebComponents([VlTemplate, VlHeader, VlFooter, VlContentHeaderComponent, VlTitleComponent]);
